import argparse
import json
import os
from pathlib import Path
import re
import selectors
import shutil
import signal
import subprocess
import sys
import time

from publish import publish

MAX_SECRET=262144


class InputTimeout(Exception):pass
class Interrupted(Exception):
    def __init__(self,code):self.code=code


def read_secret(timeout_ms):
    if not os.readlink('/proc/self/fd/0').startswith('pipe:['):
        raise ValueError('anonymous input required')
    deadline=time.monotonic()+timeout_ms/1000;chunks=[];size=0
    with selectors.DefaultSelector() as selector:
        selector.register(0,selectors.EVENT_READ)
        while True:
            remaining=deadline-time.monotonic()
            if remaining<=0 or not selector.select(remaining):raise InputTimeout()
            chunk=os.read(0,min(65536,MAX_SECRET+1-size))
            if not chunk:break
            chunks.append(chunk);size+=len(chunk)
            if size>MAX_SECRET:raise ValueError('secret length')
    secret=b''.join(chunks)
    if not secret or b'\0' in secret:raise ValueError('secret schema')
    secret.decode('utf8')
    return secret


def stop(process):
    if process is None:return
    if process.poll() is None:
        try:os.killpg(process.pid,signal.SIGTERM)
        except ProcessLookupError:pass
    try:process.communicate(timeout=.2)
    except subprocess.TimeoutExpired:
        try:os.killpg(process.pid,signal.SIGKILL)
        except ProcessLookupError:pass
        process.communicate(timeout=1)


def handle(signum,frame):
    raise Interrupted(130 if signum==signal.SIGINT else 143)


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--worker',required=True);parser.add_argument('--state',required=True)
    parser.add_argument('--target',required=True);parser.add_argument('--request-id',required=True)
    parser.add_argument('--output',required=True);parser.add_argument('--timeout-ms',type=int,default=1000)
    parser.add_argument('--input-timeout-ms',type=int,default=500)
    args=parser.parse_args();started=time.monotonic();process=None;secret=b'';result=None
    if not all(re.fullmatch('[a-z][a-z0-9_-]{0,31}',value) for value in (args.target,args.request_id)):
        print('invalid nonsecret metadata',file=sys.stderr);return 64
    diagnostic={'target_alias':args.target,'request_id':args.request_id,'stage':'prepare','classification':'unavailable',
                'exit_status':69,'worker_exit_status':None,'elapsed_ms':0}
    if os.path.lexists(args.output):
        diagnostic.update(classification='output_exists',exit_status=73)
        print(json.dumps(diagnostic),file=sys.stderr);return 73
    signal.signal(signal.SIGTERM,handle);signal.signal(signal.SIGINT,handle)
    try:
        worker=Path(args.worker).resolve()
        if not worker.is_file() or not os.access(worker,os.X_OK):raise FileNotFoundError()
        if not 100<=args.timeout_ms<=2000 or not 100<=args.input_timeout_ms<=2000:raise ValueError('time limit')
        if not os.access(Path(args.output).parent,os.W_OK|os.X_OK):raise PermissionError()
        diagnostic['stage']='secret_input'
        secret=read_secret(args.input_timeout_ms)
        diagnostic['stage']='worker'
        # No inherited Bash startup files, xtrace options, exported functions or
        # credential-bearing environment. These values configure only this child.
        environment={'PATH':os.defpath,'LANG':'C.UTF-8','LC_ALL':'C.UTF-8','PYTHONNOUSERSITE':'1','PYTHONDONTWRITEBYTECODE':'1',
                     'TMPDIR':str(Path(args.state).resolve())}
        bash=shutil.which('bash',path=os.defpath)
        process=subprocess.Popen([bash,'--noprofile','--norc',str(Path(__file__).with_name('collect.sh')),
                                  str(worker),args.target,args.request_id,str(Path(args.state).resolve())],
                                 stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,
                                 env=environment,start_new_session=True)
        raw_stdout,raw_stderr=process.communicate(input=secret,timeout=args.timeout_ms/1000)
        status=process.returncode if process.returncode>=0 else 128-process.returncode
        diagnostic['worker_exit_status']=status
        if status==0:
            diagnostic['stage']='protocol'
            def unique(pairs):
                result={}
                for key,item in pairs:
                    if key in result:raise ValueError('duplicate worker field')
                    result[key]=item
                return result
            try:
                value=json.loads(raw_stdout.decode('utf8'),object_pairs_hook=unique)
            except RecursionError:
                raise ValueError('worker protocol') from None
            if not isinstance(value,dict) or set(value)!={'records'} or type(value['records']) is not int or not 0<=value['records']<=1000000:
                raise ValueError('worker protocol')
            result={'records':value['records']};diagnostic.update(classification='success',exit_status=0)
        else:
            classification={77:'authentication',64:'invalid_request',75:'temporary'}.get(status,'worker_error')
            diagnostic.update(classification=classification,exit_status=status)
