        signal.signal(signal.SIGTERM,signal.SIG_IGN);signal.signal(signal.SIGINT,signal.SIG_IGN)
        stop(process);diagnostic.update(classification='interrupted',exit_status=error.code)
    except InputTimeout:
        diagnostic.update(classification='input_timeout',exit_status=124)
    except subprocess.TimeoutExpired:
        stop(process);diagnostic.update(classification='timeout',exit_status=124)
        diagnostic['worker_exit_status']=process.returncode if process.returncode>=0 else 128-process.returncode
    except FileNotFoundError:
        diagnostic.update(classification='unavailable',exit_status=69)
    except (ValueError,UnicodeError):
        if diagnostic['stage']=='protocol':diagnostic.update(classification='protocol',exit_status=65)
        else:diagnostic.update(classification='invalid_secret',exit_status=64)
    except OSError:
        stop(process);diagnostic.update(classification='filesystem',exit_status=73)
    finally:
        secret=b''
    # Collection/termination is complete. Finish one bounded metadata publication
    # rather than raising a second cancellation inside its atomic directory commit.
    signal.signal(signal.SIGTERM,signal.SIG_IGN);signal.signal(signal.SIGINT,signal.SIG_IGN)
    if diagnostic['exit_status']!=0:result=None
