    try:
        publish(args.output,diagnostic,result)
    except (OSError,ValueError):
        diagnostic.update(stage='prepare' if diagnostic['stage']=='prepare' else 'report',classification='filesystem',exit_status=73)
        print(json.dumps(diagnostic),file=sys.stderr);return 73
    try:
        if diagnostic['exit_status']==0:print(json.dumps({'ok':True,**result}),flush=True)
        else:print(json.dumps(diagnostic),file=sys.stderr,flush=True)
    except OSError:
        # Status publication follows the safe directory commit; never delete the
        # already-published diagnostic as if the collection had been rolled back.
        diagnostic.update(stage='report',classification='output_committed',exit_status=74)
        descriptor=os.open(os.devnull,os.O_WRONLY)
        try:os.dup2(descriptor,sys.stdout.fileno())
        finally:os.close(descriptor)
        print(json.dumps(diagnostic),file=sys.stderr);return 74
    return diagnostic['exit_status']


