import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import sys
import time


def now():
    return time.monotonic_ns() // 1000000


def load(path):
    def unique(pairs):
        out = {}
        for key, value in pairs:
            if key in out:
                raise ValueError('duplicate JSON key')
            out[key] = value
        return out
    return json.loads(Path(path).read_text(encoding='utf8'), object_pairs_hook=unique)


def encode(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False).encode('utf8')


def integer(value, minimum, maximum):
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError('policy integer outside range')
    return value


def prepare(args):
    policy = load(args.policy); request = load(args.request)
    if not isinstance(policy, dict) or set(policy) != {'max_attempts', 'total_ms', 'attempt_ms', 'base_backoff_ms', 'max_backoff_ms', 'jitter_ms', 'retryable_codes'}:
        raise ValueError('policy schema')
    for key, low, high in [('max_attempts',1,5), ('total_ms',100,5000), ('attempt_ms',25,1000),
                           ('base_backoff_ms',0,500), ('max_backoff_ms',0,1000), ('jitter_ms',0,100)]:
        integer(policy[key], low, high)
    if policy['base_backoff_ms'] > policy['max_backoff_ms']:
        raise ValueError('backoff bounds')
    codes = policy['retryable_codes']
    if not isinstance(codes, list) or not codes or any(type(code) is not int or code not in (69,75) for code in codes) or len(codes) != len(set(codes)):
        raise ValueError('only explicitly approved transient codes 69/75 may be retryable')
    if not isinstance(request, dict) or set(request) != {'operation_id', 'mode', 'payload'}:
        raise ValueError('request schema')
    if not isinstance(request['operation_id'], str) or not re.fullmatch('[A-Za-z0-9_.-]{1,128}', request['operation_id']):
        raise ValueError('operation id')
    if request['mode'] not in ('idempotent', 'queryable', 'unsafe') or not isinstance(request['payload'], str):
        raise ValueError('request mode/payload')
    target = Path(args.audit)
    if os.path.lexists(target):
        raise ValueError('audit output already exists')
    manifest = {'operation_id': request['operation_id'], 'mode': request['mode'], 'policy': policy,
                'request_sha256': hashlib.sha256(Path(args.request).read_bytes()).hexdigest(),
                'policy_sha256': hashlib.sha256(Path(args.policy).read_bytes()).hexdigest(), 'started_ms': now()}
    created = False
    try:
        target.mkdir(mode=0o700); created = True; target.chmod(0o700)
        (target/'manifest.json').write_bytes(encode(manifest)); (target/'manifest.json').chmod(0o600)
        (target/'events.jsonl').write_bytes(b''); (target/'events.jsonl').chmod(0o600)
    except Exception:
        if created:
            target.chmod(0o700); shutil.rmtree(target)
        raise
    print('\t'.join(map(str, [request['operation_id'], request['mode'], policy['max_attempts'], policy['total_ms'],
          policy['attempt_ms'], policy['base_backoff_ms'], policy['max_backoff_ms'], policy['jitter_ms'],
          ','.join(map(str, codes)), manifest['started_ms']])))


def append(args):
    root = Path(args.audit); manifest = load(root/'manifest.json')
    lines = (root/'events.jsonl').read_text().splitlines()
    previous = json.loads(lines[-1])['hash'] if lines else '0'*64
    record = {'sequence': len(lines)+1, 'phase': args.phase, 'operation_id': manifest['operation_id'],
              'attempt': args.attempt, 'time_ms': now(), 'status': args.status,
